/// <summary>
/// MPJ_5013_ExciseRegisterEntry 
/// Service class to run the update and creation of new record
/// </summary>
class METUpdateExciseRegisterService extends SysOperationServiceBase
{
    str errorMessage,infologMessage;
    
}

Method.Source:
    /// <summary>
    /// MPJ_5013_ExciseRegister
    /// Processes the Invoiced Sales order and creates entries in Excise Register accordingly
    /// </summary>
    /// <param name = "_contract">METUpdateExciseRegisterContract class for Sales Id input</param>
    public void processOperation(METUpdateExciseRegisterContract _contract)
    {
        SalesId salesId = _contract.parmSalesId();

        InventSite             inventSite;
        CustInvoiceJour        custInvoiceJour;
        CustInvoiceTrans       custInvoiceTrans;
        InventDim              inventDim;
        
        try
        {
            ttsbegin;
            _contract.parmLastExecutionStartDateTime(DateTimeUtil::utcNow());

            while select SalesId, InvoiceId from custInvoiceJour
                    where custInvoiceJour.SalesId == salesId // compare previous end time of batch job
                join InventDimId,Qty,SalesUnit,ItemId from custInvoiceTrans
                    where custInvoiceTrans.SalesId == custInvoiceJour.SalesId
                join InventSiteId from inventDim
                    where inventDim.inventDimId == custInvoiceTrans.InventDimId
                join SiteId from InventSite
                    where InventSite.SiteId             == inventDim.InventSiteId
                       && InventSite.MetBondedWarehouse == NoYes::Yes
            
            {
                this.createExciseRegisterEntryForSO(custInvoiceJour.SalesId,custInvoiceJour.InvoiceId,
                                                    custInvoiceTrans.Qty,custInvoiceTrans.SalesUnit,custInvoiceTrans.ItemId,
                                                    InventSite.SiteId);
            }
            _contract.parmLastExecutionEndDateTime(DateTimeUtil::utcNow());

            InventTransferTable transferTable;
            InventTransferLine  transferLine;
            
            while select transferTable
                where transferTable.TransferStatus == InventTransferStatus::Received;

                join transferLine
                   where transferLine.TransferId == transferTable.TransferId
            {
                InventSiteId inventSiteFrom = InventLocation::find(transferTable.InventLocationIdFrom).InventSiteId;
                InventSiteId inventSiteTo   = InventLocation::find(transferTable.InventLocationIdTo).InventSiteId;

                this.createRegisterEntryForTransfer(inventSiteFrom,inventSiteTo, transferLine.ItemId, transferLine.QtyShipped,transferLine.QtyReceived, transferLine.UnitId, transferLine.TransferId);
            }

            
            ttscommit;
        }
        catch
        {
            //If an error occurs, check if log header is available
            this.getInfologMessage();
            System.Exception ex = CLRInterop::getLastException();
            errorMessage += ex.Message + ex.ToString();
            info(errorMessage + infologMessage);
        }
    }

    /// <summary>
    /// enter the transfer Order details to Excise Register 
    /// </summary>
    /// <param name = "_fromSite">From Site</param>
    /// <param name = "_toSite">To Site</param>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_qtyShipped">qty Shipped</param>
    /// <param name = "_qtyReceived">qty Received</param>
    /// <param name = "_unit">Unit Id </param>
    /// <param name = "_transferId">Transfer id</param>
    private void createRegisterEntryForTransfer(InventSiteId _fromSite, InventSiteId _toSite, ItemId _itemId, Qty _qtyShipped, Qty _qtyReceived, InventUnitId _unit, InventTransferId _transferId)
    {
        METExciseRegisterEntry metExciseRegisterEntry;

        metExciseRegisterEntry.OriginType               =  METOriginType::TransferOrder;
        metExciseRegisterEntry.OriginNumber             = _transferId;
        //metExciseRegisterEntry.OriginDocumentNumber     = _transferId;
        
        metExciseRegisterEntry.ReceiptUnitOfMeasure     = _unit;
        metExciseRegisterEntry.ItemId                   = _itemId;

        //create entries for outgoing and incoming
        this.createRegisterEntryForTransferIncoming(metExciseRegisterEntry, _toSite,_qtyReceived);
        this.createRegisterEntryForTransferOutgoing(metExciseRegisterEntry, _fromSite, _qtyShipped);
        
    }

    private void createRegisterEntryForTransferOutgoing(METExciseRegisterEntry _registerEntry, InventSiteId _site,Qty _qty)
    {
        METExciseRegisterEntry METExciseRegisterEntry = _registerEntry.data();

        METExciseRegisterEntry.Site             = _site;
        METExciseRegisterEntry.ReceiptQuantity  = -_qty; //Outgoing will have -ve qty in register entry
        METExciseRegisterEntry.setInventUnitQty();
        
        //Create Excise Register Entries untill all the Ougoing transfer Order Units/qty is consumed or there are no more entries available for consumption
        while(METExciseRegisterEntry.Quantity != 0)
        {
            METExciseRegisterEntry.Quantity = this.insertExciseRegisterEntryOutgoing(METExciseRegisterEntry);
        }
    }

    private void createRegisterEntryForTransferIncoming(METExciseRegisterEntry _registerEntry, InventSiteId _site,Qty _qty)
    {
        METExciseRegisterEntry METExciseRegisterEntryInsert = _registerEntry.data();

        METExciseRegisterEntryInsert.Site               = _site;
        METExciseRegisterEntryInsert.ReceiptQuantity    = _qty; //Outgoing will have -ve qty in register entry
        METExciseRegisterEntryInsert.setAvailableQty();

        METExciseRegisterEntryInsert.Lodgement          = this.getLodgementDetailsForIncoming(_site,_registerEntry.ItemId);
        METExciseRegisterEntryInsert.insert();
    }

    /// <summary>
    /// create Excise Register Entry for Sales Order invoice
    /// </summary>
    /// <param name = "_salesId">Sales Id</param>
    /// <param name = "_invoiceId">Invoice Id</param>
    /// <param name = "_qty">Qty of the Invoice Line</param>
    /// <param name = "_salesUnit">Sales Unit</param>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_site">SiteId</param>
    private void createExciseRegisterEntryForSO(SalesId _salesId, InvoiceId _invoiceId, 
                                                Qty _qty, SalesUnit _salesUnit, ItemId _itemId,
                                                InventSiteId _site)
    {
        METExciseRegisterEntry metExciseRegisterEntry;
        
        metExciseRegisterEntry.OriginNumber             = _salesId;
        metExciseRegisterEntry.OriginDocumentNumber     = _invoiceId;
        metExciseRegisterEntry.ReceiptQuantity          = - _qty; //sales will have -ve qty in register entry, return orders will have +ve qty in register entry
        metExciseRegisterEntry.ReceiptUnitOfMeasure     = _salesUnit;
        metExciseRegisterEntry.ItemId                   = _itemId;
        metExciseRegisterEntry.Site                     = _site;

        if(_qty >0)
        {
            metExciseRegisterEntry.OriginType = METOriginType::SalesOrder;
            metExciseRegisterEntry.setInventUnitQty();

            //Create Excise Register Entries untill all the Sales Order Units/qty is consumed or there are no more entries available for consumption
            while(metExciseRegisterEntry.Quantity != 0)
            {
                //We will always be able to consume the purchase qty for a transfer order
                metExciseRegisterEntry.Quantity = this.insertExciseRegisterEntryOutgoing(metExciseRegisterEntry);
            }
        }
        else
        {
            metExciseRegisterEntry.OriginType   = METOriginType::SalesOrderReturn;
            metExciseRegisterEntry.Lodgement    = this.getLodgementDetailsForIncoming(_site,_itemId);
        
            metExciseRegisterEntry.insert();
        }
    }

    /// <summary>
    /// Get Lodgment Details for a Return Sales Order
    ///    check for latest open Purchase Entry which is under consumption, use that as lodgment details
    ///    - If no open purchase found, use the latest closed entry line for lodgement details
    /// </summary>
    /// <param name = "_siteId">SiteId</param>
    /// <param name = "_itemId">ItemId</param>
    /// <returns>excise register record for lodgement reference</returns>
    private METLodgement getLodgementDetailsForIncoming(InventSiteId _siteId,ItemId _itemId)
    {
        METExciseRegisterEntry metExciseRegisterEntry;

        //find current Open excise register line for Lodgement Number which is under consumption
        metExciseRegisterEntry = this.findOldestExciseRegisterEntry(_itemId,_siteId,METOriginType::PurchaseOrder,NoYes::No);
        if(metExciseRegisterEntry.Recid)
        {
            return metExciseRegisterEntry.Lodgement;
        }
        
        //if open line not found, find the latest closed line
        select firstonly Lodgement from metExciseRegisterEntry
        order by metExciseRegisterEntry.CreatedDateTime desc
        where (metExciseRegisterEntry.OriginType   == METOriginType::PurchaseOrder || metExciseRegisterEntry.OriginType   == METOriginType::TransferOrder)
            && metExciseRegisterEntry.Site        == _siteId
            && metExciseRegisterEntry.ItemId      == _itemId
            && metExciseRegisterEntry.Closed      == NoYes::Yes;

        //shouldn't be blank as we will always have atleast 1 purchase line before sales
        return metExciseRegisterEntry.Lodgement;
    }

    /// <summary>
    /// Create new record for Sales Order and update the consumed Purchase Order record in the Excise Register table
    /// </summary>
    /// <param name = "_metExciseRegisterEntry">base Excise register data to be created</param>
    /// <returns>remaining qty available from Sales Order that can be settled against another purchase/return sales order</returns>
    private SalesQty insertExciseRegisterEntryOutgoing(METExciseRegisterEntry _metExciseRegisterEntry)
    {
        METExciseRegisterEntry METExciseRegisterEntryInsert = _metExciseRegisterEntry.data();//copy data into new record (dont make changes in the variable record)

        //find the record against which SO quantity to be settled against.
        METExciseRegisterEntry metExciseRegisterEntryPurchase = this.findExciseRegisterEntryForSettlement(METExciseRegisterEntryInsert.ItemId,METExciseRegisterEntryInsert.Site);
        
        SalesQty availableQtyToSettle;

        if(metExciseRegisterEntryPurchase.RecId)
        {
            metExciseRegisterEntryPurchase.selectForUpdate(true);

            METExciseRegisterEntryInsert.Lodgement = metExciseRegisterEntryPurchase.Lodgement;
            
            //IF Settlement (+ve qty) record has more available quantity than the SO qty, subtract SO quantity from the available quantity of Settlement record
            if(metExciseRegisterEntryPurchase.AvailableQuantity >= abs(METExciseRegisterEntryInsert.Quantity))
            {
                metExciseRegisterEntryPurchase.AvailableQuantity = metExciseRegisterEntryPurchase.AvailableQuantity + METExciseRegisterEntryInsert.Quantity;
                metExciseRegisterEntryPurchase.Closed = metExciseRegisterEntryPurchase.AvailableQuantity==0? NoYes::Yes : NoYes::No;
                metExciseRegisterEntryPurchase.update();
                availableQtyToSettle = 0;
            }
            else
            {
                //IF Settlement (+ve qty) record has less available qty, make availabl qty 0 and close the current settlement record.
                    //Carry forward the remaining SO qty to settle against the next Settlement record
                METExciseRegisterEntryInsert.Quantity = - metExciseRegisterEntryPurchase.AvailableQuantity;

                availableQtyToSettle = _metExciseRegisterEntry.Quantity + metExciseRegisterEntryPurchase.AvailableQuantity;
                metExciseRegisterEntryPurchase.AvailableQuantity = 0;
                metExciseRegisterEntryPurchase.Closed = NoYes::Yes;
                metExciseRegisterEntryPurchase.update();
            }
            
            METExciseRegisterEntryInsert.insert();
        }
        return availableQtyToSettle;
    }

    /// <summary>
    /// Find the Excise Register Record against which we need to settle the SO qty
    ///     Return Sales Order is preferred over Purchase order even if Purchase order was previously consumed.
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_site">Site Id</param>
    /// <returns>METExciseRegisterEntry record</returns>
    private METExciseRegisterEntry findExciseRegisterEntryForSettlement(ItemId _itemId,InventSiteId _site)
    {
        METExciseRegisterEntry metExciseRegisterEntry;

        //find Return Sales order entry for Settlement first
        metExciseRegisterEntry = this.findOldestExciseRegisterEntry(_itemId,_site,METOriginType::SalesOrderReturn,NoYes::No);

        if(metExciseRegisterEntry)
        {
            return metExciseRegisterEntry;
        }

        //find oldest open Purchase order entry for Settlement first
        metExciseRegisterEntry = this.findOldestExciseRegisterEntry(_itemId,_site,METOriginType::PurchaseOrder,NoYes::No);

        return metExciseRegisterEntry;
    }

    /// <summary>
    /// Find the Excise Register Record against which we need to settle the SO qty based on Origin Type
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_site">Site Id</param>
    /// <param name = "_OriginType">Origin Type</param>
    /// <param name = "_isClosed">Is Excise Register line closed</param>
    /// <returns>METExciseRegisterEntry record</returns>
    private METExciseRegisterEntry findOldestExciseRegisterEntry(ItemId _itemId,InventSiteId _site,METOriginType _OriginType, NoYes _isClosed)
    {
        METExciseRegisterEntry metExciseRegisterEntry;

        if(_OriginType == METOriginType::SalesOrderReturn)
        {
            select firstonly metExciseRegisterEntry
                order by createdDateTime asc
                where metExciseRegisterEntry.Site       == _site
                   && metExciseRegisterEntry.ItemId     == _itemId
                   && metExciseRegisterEntry.Closed     == _isClosed
                   && metExciseRegisterEntry.OriginType == _OriginType
                   && metExciseRegisterEntry.Quantity   > 0;
        }
        else
        {
            select firstonly metExciseRegisterEntry
                order by createdDateTime asc
                where metExciseRegisterEntry.Site       == _site
                   && metExciseRegisterEntry.ItemId     == _itemId
                   && metExciseRegisterEntry.Closed     == _isClosed
                   && (
                        metExciseRegisterEntry.OriginType == METOriginType::PurchaseOrder
                     || metExciseRegisterEntry.OriginType == METOriginType::TransferOrder
                    )
                   && metExciseRegisterEntry.Quantity   > 0;
        }
        return metExciseRegisterEntry;
    }

    /// <summary>
    /// Copied from MPJ_5046_MetpayInterfaces 05/05/2021
    /// This method gets the info of the error into a variable
    /// </summary>
    private void getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;
        errorMessage    = '';
        infologMessage  = '';
        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());

            if (sysInfologEnumerator.currentException() == Exception::Error)
            {
                errorMessage += strfmt(sysInfologMessageStruct.message());
            }
            infologMessage += strfmt(sysInfologMessageStruct.message());
        }
    }
